  static Mesh GroundMesh()
  {
   const int n=100;var mesh=new Mesh{name="Original continuous rolling farm surface"};var vertices=new Vector3[(n+1)*(n+1)];var uv=new Vector2[vertices.Length];var triangles=new int[n*n*6];for(int z=0;z<=n;z++)for(int x=0;x<=n;x++){int i=z*(n+1)+x;float wx=(x/(float)n-.5f)*600,wz=(z/(float)n-.5f)*600;vertices[i]=Ground(wx,wz);uv[i]=new Vector2(x/(float)n,z/(float)n);}for(int z=0;z<n;z++)for(int x=0;x<n;x++){int i=z*(n+1)+x,t=(z*n+x)*6;triangles[t]=i;triangles[t+1]=i+n+1;triangles[t+2]=i+1;triangles[t+3]=i+1;triangles[t+4]=i+n+1;triangles[t+5]=i+n+2;}mesh.vertices=vertices;mesh.uv=uv;var meadow=new List<int>();var path=new List<int>();for(int z=0;z<n;z++)for(int x=0;x<n;x++){float wx=((x+.5f)/n-.5f)*600,wz=((z+.5f)/n-.5f)*600;bool worn=(Mathf.Abs(wx)<5&&Mathf.Abs(wz)>50&&Mathf.Abs(wz)<112)||(Mathf.Abs(wz)<5&&Mathf.Abs(wx)>50&&Mathf.Abs(wx)<112);var list=worn?path:meadow;for(int k=0;k<6;k++)list.Add(triangles[(z*n+x)*6+k]);}mesh.subMeshCount=2;mesh.SetTriangles(meadow,0);mesh.SetTriangles(path,1);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,"Assets/"+Folder+"/Models/Continuous rolling farm.asset");return mesh;
  }
