  static void Fit(Transform parent,string path,Vector3 requested)
  {
   var original=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(original==null)throw new InvalidOperationException("Installed actual farm model required: "+path);var copy=SportsReplayVisuals.Copy(original.transform);copy.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);var renderers=copy.GetComponentsInChildren<Renderer>();var b=renderers[0].bounds;foreach(var rr in renderers)b.Encapsulate(rr.bounds);float scale=Mathf.Min(requested.x/b.size.x,requested.y/b.size.y,requested.z/b.size.z);copy.transform.localScale*=scale;copy.transform.position=-new Vector3(b.center.x,b.min.y,b.center.z)*scale;copy.transform.SetParent(parent,false);
  }
